import{_ as t,o,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第94章 七秒","description":"","frontmatter":{},"headers":[],"relativePath":"第94章_七秒.md","filePath":"第94章_七秒.md"}'),u={name:"第94章_七秒.md"};function _(q,p,r,n,s,c){return o(),e("div",null,[...p[0]||(p[0]=[a('<h1 id="第94章-七秒" tabindex="-1">第94章 七秒 <a class="header-anchor" href="#第94章-七秒" aria-label="Permalink to &quot;第94章 七秒&quot;">​</a></h1><p>她跟她妈摊牌，是在十二月初。</p><p>她事先没跟我说。</p><p>我是事后知道的，是她自己讲的。</p><p>那一次她在旧号上，讲得很平。</p><p>她说，我今天跟我妈讲了我不做那个专业了。</p><p>我说，她怎么说。</p><p>她说，她先是不说话。</p><p>她说，不说话那一段大概有四十秒。</p><p>她说，四十秒以后她讲了一句，她说&quot;你想清楚了&quot;。</p><p>我说，这不是质问。</p><p>她说，对。</p><p>她说，这句最难。</p><p>她说，她要是骂我，我就骂回去。</p><p>她说，她要是哭，我就走开。</p><p>她说，她讲&quot;你想清楚了&quot;，我就要回答。</p><p>我说，你怎么回答。</p><p>她说，我说清楚了。</p><p>她说，她&quot;哦&quot;了一声。</p><p>她说，然后她去把阳台那个衣服收了。</p><p>她说，那天在下雨，她本来不打算收。</p><p>她说，我妈这个人她一难受就去干活。</p><p>她说，她收衣服收了四十分钟。</p><p>她说，我在屋里听着那个衣架碰阳台栏杆，碰了三次。</p><p>我说，那你现在什么感觉。</p><p>她说，我今天第一次觉得我这一辈子欠她的，全部在这一件衣服上。</p><p>她说，她收衣服的时候没有说一句。</p><p>她说，她一句也没说。</p><p>她说，我要是她骂我一次，我今天晚上就好过。</p><p>她说，她不骂我。</p><p>她说，她把衣服抱进来，抖了两下，跟我说了一句&quot;你晚上吃什么&quot;。</p><p>她说，我那天晚上跟她一起吃的。</p><p>我说，吃什么。</p><p>她说，面。</p><p>她说，她煮的，她给我卧了一个蛋。</p><p>她说，我吃的时候她说了一句。</p><p>她说，她说&quot;你从小就这样，你决定的事没人能改&quot;。</p><p>她说，她讲这句的时候没有抬头。</p><p>她说，我知道她这句话里有多少东西。</p><p>她说，她说的是她没有办法。</p><p>她说，她说的是她这一辈子只能把这句话讲出来。</p><p>那天晚上她在新的号上跟我讲了很久。</p><p>她讲了她那个专业这两年她是怎么念下来的。</p><p>她说，她第一年每周去一次，每次在楼下坐二十分钟才上楼。</p><p>她说，她有一次在那个楼的厕所里吐了。</p><p>她说，她跟我姨说是吃坏了。</p><p>她说，她一年没跟我妈讲过一句她不想念。</p><p>她说，我不是忍，我是找不到一个能讲的日子。</p><p>她说，我妈生日那天我讲了，她那天在笑，我不忍心。</p><p>她说，我爸回来那天我讲了，我妹在场，我不忍心。</p><p>她说，阿婆走那天我本来要讲，我站在那里我讲不出来。</p><p>我说，那你今年为什么讲得出。</p><p>她说，因为今年我口袋里有钱。</p><p>她说，不多，一万二。</p><p>她说，我这一万二是我自己挣的，我不用跟她要任何东西。</p><p>她说，我要是跟她要过一块钱，我今天这句话就讲不成。</p><p>她说，我拿她的钱念我不喜欢的东西，念完了我就没有资格说不。</p><p>她说，我今天有。</p><p>那天夜里我在本子上抄下了这一句。</p><p>抄完我在下面写了一句我自己的话。</p><p>我写：她要一个说&quot;不&quot;的资格，用了五年，攒了一万二。</p><p>我写：我要一个说&quot;我要&quot;的资格，用了四年，一次也没说过。</p><p>十二月中旬，她妈做了一件事。</p><p>她妈在旧号上给她发了一条消息。</p><p>那条消息是一张照片。</p><p>照片里是一张银行卡。</p><p>卡上面是她自己的名字。</p><p>她妈配了五个字：你自己留着。</p><p>她给我看那张图的时候，手都在抖。</p><p>她说，这里面有三万。</p><p>她说，是她这十年存下来的。</p><p>她说，她本来是要给我妹买房的。</p><p>她说，我今天拿到这个，我就没有回头路了。</p><p>我说，那你收吗。</p><p>她说，我不知道。</p><p>她说，我要是收了，我今天讲的&quot;我不念了&quot;就变成我拿她的钱去干她想不到的事。</p><p>她说，我要是不收，我就是把她十年那一点心意，原样推回去。</p><p>她说，你跟我说怎么办。</p><p>我这辈子第一次听她问我怎么办。</p><p>我拿着手机，想了很久。</p><p>我说，你收。</p><p>她说，为什么。</p><p>我说，你不收，她以后每一年都在想她那年给你了你没要。</p><p>我说，你要了，她这笔钱就变成了她支持过你。</p><p>我说，一个母亲能拿到的最好的一句话就是&quot;我支持过她&quot;。</p><p>她说，你这个人今天怎么这么会讲。</p><p>我说，我在学你。</p><p>她说，你学不像。</p><p>她说，你这一年说的话加起来，没有我今天这一句长。</p><p>她说，你今天讲了三句，我这一辈子第一次听见你连着给我讲三句主意。</p><p>她说，你以前都是&quot;你自己定&quot;。</p><p>我说，我以前不敢定。</p><p>她说，你现在怎么敢了。</p><p>我坐在那儿。</p><p>我说，因为我今年算清楚了，我考不上宁城。</p><p>我说，我明年要在这儿，我要给自己找一个别的活法。</p><p>我说，我今天给你定这三句，是因为我今天要走了。</p><p>那天她说了一句很短的话。</p><p>她说，你先说你要去哪儿。</p><p>我说，我还没定。</p><p>她说，那你不算走。</p><p>她说，你只是不定。</p><p>她说，你别拿不定当走，我分得出来。</p><p>那天我们没再讲这个。</p><p>十二月底她跟我讲的最后一句，是关于那张卡。</p><p>她说，我收了。</p><p>她说，我今天去银行把钱转到我名下了。</p><p>她说，我转完我在银行门口站着，我给我妈打了一个电话。</p><p>我说，你跟她讲什么。</p><p>她说，我什么都没说。</p><p>她说，我就&quot;喂&quot;了一声。</p><p>她说，她也&quot;喂&quot;了一声。</p><p>她说，然后我们两个都挂了。</p><p>她说，这个电话一共七秒。</p><p>她说，我这辈子打过最好的一个电话是七秒。</p><p>一月何叶跟我讲了一件事。</p><p>她说，你那天以后，她妈去阳台收了两次衣服。</p><p>我说，一天收两次？</p><p>她说，那天晚上九点多收进去一次，十一点又抱出来一次。</p><p>她说，那件衣服是干的。</p><p>她说，她就是需要一个地方站着。</p><p>她说，她在那个阳台上站了得有一个多钟头。</p><p>她说，她在下面打电话，打给她妹妹，打给她一个同事，谁都没讲什么事。</p><p>她说，她只是跟人讲话。</p><p>我那天晚上把这些告诉了她。</p><p>她听完很久没回。</p><p>然后她说了一句。</p><p>她说，她那天在阳台上肯定在想她当年怎么没人给她留一件衣服。</p><p>她说，我今天跟她讲“我想学画画”的时候，她去把衣服收了。</p><p>她说，她不是难受我的事。</p><p>她说，她是想起她自己那年没有去收衣服。</p><p>我说，那你现在知道怎么跟她讲了吗。</p><p>她说，我不知道。</p><p>她说，我今天把那张卡收了，就是我知道怎么讲了。</p>',134)])])}const l=t(u,[["render",_]]);export{d as __pageData,l as default};
